'use strict';

exports.ConnectionSerialization = require('./ConnectionSerialization');
exports.NSwizzle = require('./NSwizzle');
exports.NCommand = require('./NCommand');
exports.NAttributeElement = require('./NAttributeElement');

const ConnectionSerialization = require('./ConnectionSerialization');
const ConnectionHeartBeat = require('./ConnectionHeartBeat');
const ConnectionResponse = require('./ConnectionResponse');
const ConnectionRequest = require('./ConnectionRequest');
const NProtocolPackageMulti = require('./NProtocolPackageMulti');
const NSubscriberRegReqPacket = exports.NSubscriberRegReqPacket = require('./NSubscriberRegReqPacket');
const NPublisherRegReqPacket = exports.NPublisherRegReqPacket = require('./NPublisherRegReqPacket');
const NPublisherDataElement = exports.NPublisherDataElement = require('./NPublisherDataElement');

const ZONE = 'zone';

const ELEMENT_TYPE = exports.ELEMENT_TYPE = {
  SUBSCRIBER: 'SUBSCRIBER',
  MULTISUBSCRIBER: 'MULTISUBSCRIBER',
  PUBLISHER: 'PUBLISHER',
};

exports.CONFIG_SERVERLIST_DATAID = 'com.taobao.config.serverlist';
exports.HEADER_LENGTH = ConnectionSerialization.HEADER_LENGTH;

exports.deserialize = ConnectionSerialization.deserialize;
exports.deserializeHeader = ConnectionSerialization.deserializeHeader;
exports.deserializeBody = ConnectionSerialization.deserializeBody;

let REQUEST_ID = 1;

function getClientId(name) {
  return `${name}.${process.pid}`;
}

exports.getClientId = getClientId;

exports.createNSAppRequest = function(config) {
  const dataId = config.dataId || config.interfaceName;
  const clientId = getClientId(dataId);
  const regPacket = NSubscriberRegReqPacket(clientId, dataId);
  return NProtocolPackageMulti({
    scope: ZONE,
    dataId,
    clientId,
    regPacket,
    elementtype: ELEMENT_TYPE.SUBSCRIBER,
    appName: 'NETWORK.SERVICE',
  });
};

exports.createPublisherNSAppRequest = function(config) {
  const dataId = config.dataId || config.interfaceName;
  const groupId = config.group || config.groupId;
  const clientId = getClientId('com.taobao.notify.remotingclient.DefaultNotifyManager');
  const publishData = config.publishData;
  // 注销，默认 false
  const unregister = config.unregister || false;
  const regPacket = NPublisherRegReqPacket(clientId, dataId, groupId);
  const packet = NProtocolPackageMulti({
    scope: ZONE,
    groupId,
    dataId,
    clientId,
    regPacket,
    elementtype: ELEMENT_TYPE.PUBLISHER,
    appName: config.appName,
  });
  packet.$.elements.push(NPublisherDataElement(clientId, dataId, false, publishData, unregister));
  return packet;
};

exports.createSubscriberRegRequest = function(config) {
  const dataId = config.dataId || config.interfaceName;
  if (dataId.indexOf('NS_') === 0) {
    return exports.createNSAppRequest(config);
  }
  let groupId = config.group || config.groupId;

  if (dataId === exports.CONFIG_SERVERLIST_DATAID) {
    groupId = null;
  }

  const clientId = getClientId(config.name || config.appName || dataId);
  const regPacket = NSubscriberRegReqPacket(clientId, dataId, groupId, config.instanceId);
  return NProtocolPackageMulti({
    scope: ZONE,
    groupId,
    dataId,
    clientId,
    regPacket,
    elementtype: config.elementtype,
    appName: config.appName,
    instanceId: config.instanceId,
    accessKey: config.accessKey,
    accessSecret: config.accessSecret,
  });
};

exports.createPublisherRegRequest = function(config) {
  const dataId = config.dataId || config.interfaceName;
  if (dataId.indexOf('NS_') === 0) {
    return exports.createPublisherNSAppRequest(config);
  }
  const groupId = config.gourp || config.groupId;
  const clientId = config.clientId;
  // 注销，默认 false
  const unregister = config.unregister || false;
  const regPacket = NPublisherRegReqPacket(clientId, dataId, groupId, null, config.instanceId);
  const packet = NProtocolPackageMulti({
    scope: ZONE,
    groupId: groupId || 'SOFA',
    dataId,
    clientId,
    regPacket,
    elementtype: ELEMENT_TYPE.PUBLISHER,
    appName: config.appName,
    instanceId: config.instanceId,
    accessKey: config.accessKey,
    accessSecret: config.accessSecret,
  });

  packet.$.elements.push(NPublisherDataElement(clientId, dataId, false, config.publishData || config.url, unregister));
  return packet;
};

exports.createConnectionRequest = function(appObject) {
  return ConnectionRequest(REQUEST_ID++, appObject);
};

exports.createConnectionHeartBeat = function(clientUrl) {
  return ConnectionHeartBeat(clientUrl);
};

exports.createConnectionResponse = function(socket, requestId, resultCode, err) {
  const appObject = NProtocolPackageMulti();
  return ConnectionResponse(socket, requestId, appObject, resultCode, err);
};

exports.encode = function(packet) {
  return ConnectionSerialization.serialize(packet);
};

exports.getClassName = function(obj) {
  return obj.$class.name;
};

exports.isRequest = function(connObject) {
  return connObject.isRequest;
};

exports.getRequestId = function(obj) {
  // 有2个场景.
  if (obj.ctx) {
    return obj.ctx.id;
  }
  return obj.$.ctx.$.id;
};

exports.getRequestContent = function(connObject) {
  return connObject.appObject;
};
